create or replace function public.get_organization_revenue_trends(p_org uuid,p_days integer default 30) returns table(day date,gross_minor bigint,refunded_minor bigint,net_minor bigint) language sql stable security definer set search_path='' as $$ select l.created_at::date,sum(l.gross_amount_minor)::bigint,sum(l.refunded_amount_minor)::bigint,sum(l.organizer_net_minor)::bigint from public.paid_vote_ledger l where l.organization_id=p_org and private.is_org_member(p_org) and l.status in ('confirmed','refunded','reversed') and l.created_at>=current_date-greatest(1,least(p_days,365)) group by l.created_at::date order by 1; $$;
revoke all on function public.get_organization_revenue_trends(uuid,integer) from public,anon; grant execute on function public.get_organization_revenue_trends(uuid,integer) to authenticated;
